<div class="page-title"><div><em>LENDING</em><h1>Loans & credit</h1><p>Manage your borrowing and explore personalized offers.</p></div><button class="btn" data-modal="loan-modal">Apply for a loan</button></div><?php if(!$loans):?><div class="empty">You don't have any active loans. Apply for one below.</div><?php endif?><?php foreach($loans as $l):?><section class="loan-hero"><div><small><?=strtoupper($l['type'])?></small><h2><?=money($l['outstanding_balance'])?></h2><p>Remaining balance</p><div class="progress"><i style="width:<?=100-($l['outstanding_balance']/$l['principal']*100)?>%"></i></div><span><?=round(100-($l['outstanding_balance']/$l['principal']*100))?>% repaid · <?=$l['payments_remaining']?> payments remaining</span></div><div><small>NEXT PAYMENT</small><h3><?=money($l['monthly_payment'])?></h3><p>Due <?=date('F j, Y',strtotime($l['next_payment_date']))?></p><button>Make a payment</button></div></section><div class="stats"><div><i>▥</i><span>Original amount<b><?=money($l['principal'])?></b></span></div><div><i>%</i><span>Interest rate<b><?=$l['interest_rate']?>% APR</b></span></div><div><i>✓</i><span>Paid to date<b><?=money($l['principal']-$l['outstanding_balance'])?></b></span></div></div><?php endforeach?><section class="panel offer"><div><small>PRE-APPROVED OFFER</small><h2>Reach your next goal with up to $50,000</h2><p>A competitive fixed rate, no origination fee and fast funding.</p><button class="btn">View my rate</button></div><i>$</i></section>

<dialog id="loan-modal"><div class="dialog-head"><h2>Apply for a loan</h2><button data-close>×</button></div><?=form_open('loans/create')?><label>Loan type</label><select name="type"><option>Personal loan</option><option>Auto loan</option><option>Home improvement</option><option>Education</option></select><div class="form-grid"><div><label>Amount</label><input name="amount" type="number" step="0.01" min="100" max="250000" required placeholder="10,000"></div><div><label>Term (months)</label><input name="term_months" type="number" min="6" max="120" value="36" required></div></div><label>Fixed APR (%)</label><input name="interest_rate" type="number" step="0.001" value="6.250"><button class="btn wide">Apply now</button></form></dialog>
